import { createContext } from 'react'

/**
 * How a ChatMessage reaches its ChatThread's one polite status region. Not public: ChatThread
 * provides it and ChatMessage reads it, so a message outside a thread simply announces nothing.
 *
 * `live()` says whether the thread has finished its first render. A message that was already
 * there (the history a thread opens with) is never announced; one that arrives later is, once.
 */
export type ChatAnnouncer = {
  announce: (text: string) => void
  live: () => boolean
}

export const ChatAnnouncerContext = createContext<ChatAnnouncer | null>(null)

/** Blocks inside a message that are not its reply (a ToolCall, an ApprovalRequest) carry this
 *  attribute, and the announcement leaves them out: "Done, 1.2 s, Show details" read out after
 *  every reply is noise, and each block is its own stop for a reader browsing the log. */
export const CHAT_BLOCK_ATTRIBUTE = 'data-chat-block'

/** The text of a finished message, without its blocks, in one line. */
export function announcementText(body: HTMLElement): string {
  const copy = body.cloneNode(true) as HTMLElement
  copy.querySelectorAll(`[${CHAT_BLOCK_ATTRIBUTE}]`).forEach(block => block.remove())
  return (copy.textContent ?? '').replace(/\s+/g, ' ').trim()
}

import { useContext, useEffect, useId, useRef, type ReactNode } from 'react'
import { cn } from '../../../lib/cn'
import { ChatAnnouncerContext, announcementText } from './announcer'

export type ChatMessageRole = 'user' | 'assistant' | 'system'

export type ChatMessageProps = {
  /** Who is speaking. `system` is a quiet centred status line: "Assistant stopped". */
  role: ChatMessageRole
  /** Required. "You", "Assistant". Shown above the message and names it for a screen reader. */
  author: string
  /** ISO datetime, for `<time dateTime>`. */
  time?: string
  /** What is shown for the time: "09:40". */
  timeLabel?: string
  /** Still arriving: `aria-busy` on the message, and a caret after the text. In a ChatThread the
   *  finished text is announced once, when this turns false; never word by word. @default false */
  streaming?: boolean
  /** Text, paragraphs, or ToolCall and ApprovalRequest blocks. */
  children: ReactNode
  /** Small buttons under an assistant message: Copy, Retry. */
  actions?: ReactNode
  className?: string
}

/**
 * One turn in a conversation. An `article` named by its author line, so a screen reader browsing a
 * ChatThread's log hears "You" or "Assistant" at the start of each message and can jump between
 * them by landmark-like article navigation.
 *
 * The three roles read differently on purpose. The person's own words sit in a sunken bubble on
 * the right, the shape every chat has taught them; the assistant's reply has no bubble and the
 * full width, because it is the long text and holds blocks (tool calls, approvals) that need the
 * room; a system line is a mono label in the middle, for the conversation's own events.
 *
 * Streaming. `aria-busy` says the message is incomplete to anyone who reaches it mid-stream. The
 * caret is a static block, not a blink: a blink that lasts as long as the stream would be content
 * that flashes for more than five seconds with no way to stop it (SC 2.2.2), and reduced motion
 * would have to remove it anyway. Inside a ChatThread, the message tells the thread its finished
 * text when `streaming` turns false (or when it arrives already complete), and the thread reads it
 * out once through its status region. Blocks marked as such are left out of that text.
 *
 * Contrast rows, by exact name. User bubble text: "toast title (text.primary) on surface.sunken".
 * Assistant text: "text.primary on surface.base". Author, time and the system line: "text.secondary
 * on surface.base". The caret is decorative (a pseudo-element), the bubble's border a hairline.
 */
export function ChatMessage({
  role,
  author,
  time,
  timeLabel,
  streaming = false,
  children,
  actions,
  className,
}: ChatMessageProps) {
  const authorId = useId()
  const bodyRef = useRef<HTMLDivElement>(null)
  const thread = useContext(ChatAnnouncerContext)
  // Decided once, at the first effect: was this message part of the history the thread opened
  // with? A message that mounted while still streaming is new, whatever the thread says.
  const arrivedLive = useRef<boolean | null>(null)
  const announced = useRef(false)

  useEffect(() => {
    if (!thread || role === 'user' || announced.current) return
    if (arrivedLive.current === null) arrivedLive.current = streaming || thread.live()
    if (!arrivedLive.current || streaming || !bodyRef.current) return
    // A reply that so far holds only a running ToolCall has nothing to say yet; it is announced
    // when its text has streamed in.
    const text = announcementText(bodyRef.current)
    if (!text) return
    announced.current = true
    thread.announce(role === 'system' ? text : `${author}: ${text}`)
  }, [thread, role, author, streaming])

  const timeElement =
    timeLabel === undefined ? null : (
      <time
        dateTime={time}
        className="font-mono text-xs uppercase tracking-[0.12em] tabular-nums text-[var(--color-text-secondary)]"
      >
        {timeLabel}
      </time>
    )

  // The caret is a ::after on the body's last paragraph, so it sits at the end of the text even
  // when the message also holds blocks (a ToolCall above the reply). A pseudo-element with empty
  // content is not in the accessibility tree. No paragraph yet (only a running ToolCall), no caret.
  const caret =
    "[&>p:last-child]:after:content-[''] [&>p:last-child]:after:inline-block [&>p:last-child]:after:w-[0.5em] [&>p:last-child]:after:h-[1.1em] [&>p:last-child]:after:ml-0.5 [&>p:last-child]:after:align-text-bottom [&>p:last-child]:after:bg-[var(--color-accent-signal-fill)]"

  if (role === 'system') {
    return (
      <article
        aria-labelledby={authorId}
        aria-busy={streaming || undefined}
        className={cn('anim-snap-in flex items-center gap-3', className)}
      >
        <span aria-hidden="true" className="h-px grow bg-[var(--color-border-hairline)]" />
        <span id={authorId} className="sr-only">
          {author}
        </span>
        <div
          ref={bodyRef}
          className="font-mono text-xs font-semibold uppercase tracking-[0.18em] text-center text-[var(--color-text-secondary)]"
        >
          {children}
          {timeElement ? <> · {timeElement}</> : null}
        </div>
        <span aria-hidden="true" className="h-px grow bg-[var(--color-border-hairline)]" />
      </article>
    )
  }

  const user = role === 'user'
  return (
    <article
      aria-labelledby={authorId}
      aria-busy={streaming || undefined}
      data-role={role}
      className={cn('anim-snap-in flex flex-col gap-1.5 min-w-0', user ? 'items-end' : 'items-stretch', className)}
    >
      <div className="flex items-baseline gap-3">
        <span
          id={authorId}
          className="font-mono text-xs font-semibold uppercase tracking-[0.18em] text-[var(--color-text-secondary)]"
        >
          {author}
        </span>
        {timeElement}
      </div>
      <div
        ref={bodyRef}
        data-part="body"
        data-streaming={streaming ? '' : undefined}
        className={cn(
          'flex flex-col gap-3 min-w-0 font-body text-sm leading-relaxed text-[var(--color-text-primary)] break-words',
          user && 'max-w-[85%] px-3 py-2 border border-[var(--color-border-hairline)] bg-[var(--color-surface-sunken)]',
          streaming && caret
        )}
      >
        {typeof children === 'string' ? <p>{children}</p> : children}
      </div>
      {actions === undefined || user ? null : <div className="flex flex-wrap gap-2 mt-1">{actions}</div>}
    </article>
  )
}

import { useEffect, useId, useRef, useState, type ReactNode } from 'react'
import { ThumbsDown, ThumbsUp } from 'lucide-react'
import { cn } from '../../../lib/cn'
import { Button } from '../../atoms/button/Button'
import { IconButton } from '../../atoms/icon-button/IconButton'
import { Textarea } from '../../atoms/textarea/Textarea'
import { Tooltip } from '../../atoms/tooltip/Tooltip'

export type FeedbackVote = 'helpful' | 'not-helpful'

export type ResponseFeedbackProps = {
  /** Required. Runs on a vote. Return a promise to show "Submitting feedback" until it settles; a
   *  rejection puts both buttons back and says the feedback was not sent. */
  onSubmit: (vote: FeedbackVote) => void | Promise<void>
  /** Offers the optional "tell us more" step after a Not helpful vote. Without it, there is none. */
  onDetail?: (text: string) => void
  className?: string
}

type Phase = 'idle' | 'submitting' | 'submitted' | 'failed'
type Detail = 'closed' | 'open' | 'sent'

/** Cloudscape's wording, word for word: the tooltip on each button, before and after a vote. */
const TIP = {
  helpful: {
    idle: 'Helpful',
    chosen: '"Helpful" feedback has been submitted.',
    other: '"Helpful" option is unavailable after "not helpful" feedback submitted.',
  },
  'not-helpful': {
    idle: 'Not helpful',
    chosen: '"Not helpful" feedback has been submitted.',
    other: '"Not helpful" option is unavailable after "helpful" feedback submitted.',
  },
} as const

/**
 * Thumbs up and down under an assistant reply, for ChatMessage's `actions`. Only on generated
 * replies: never on a person's own message, and never as feedback on the page itself.
 *
 * One vote per reply. While it is sent both buttons are aria-disabled and the status line says
 * "Submitting feedback"; then "Feedback submitted", the chosen button stays pressed, and each
 * button's tooltip says why it no longer works. aria-disabled and not `disabled`, so the buttons
 * stay tab stops: a disabled button gets no hover or focus, so its tooltip, the reason, could
 * never be read.
 *
 * A Not helpful vote with `onDetail` opens an optional step under the buttons: a box and Send /
 * Dismiss. Inline, not a dialog: the reply stays readable while a person writes about it, and
 * nothing traps focus for a step that is optional. Focus moves to the box when it opens and to the
 * status line when it closes, because the element that had it is gone.
 */
export function ResponseFeedback({ onSubmit, onDetail, className }: ResponseFeedbackProps) {
  const id = useId()
  const [phase, setPhase] = useState<Phase>('idle')
  const [vote, setVote] = useState<FeedbackVote | null>(null)
  const [detail, setDetail] = useState<Detail>('closed')
  const [text, setText] = useState('')
  const boxRef = useRef<HTMLTextAreaElement>(null)
  const statusRef = useRef<HTMLParagraphElement>(null)

  useEffect(() => {
    if (detail === 'open') boxRef.current?.focus()
  }, [detail])

  const choose = async (choice: FeedbackVote) => {
    if (phase === 'submitting' || phase === 'submitted') return
    setVote(choice)
    setPhase('submitting')
    try {
      await onSubmit(choice)
    } catch {
      setPhase('failed')
      setVote(null)
      return
    }
    setPhase('submitted')
    if (choice === 'not-helpful' && onDetail) setDetail('open')
  }

  const closeDetail = (sent: boolean) => {
    if (sent) onDetail?.(text)
    setDetail(sent ? 'sent' : 'closed')
    // The box and its buttons are about to unmount; focus would fall to the page.
    requestAnimationFrame(() => statusRef.current?.focus())
  }

  const locked = phase === 'submitting' || phase === 'submitted'
  const button = (choice: FeedbackVote, icon: ReactNode) => {
    const tip = !locked ? TIP[choice].idle : vote === choice ? TIP[choice].chosen : TIP[choice].other
    return (
      <Tooltip content={tip}>
        <IconButton
          variant="ghost"
          size="sm"
          label={TIP[choice].idle}
          aria-pressed={vote === choice}
          // The chosen thumb is filled, so the vote shows in shape and not only in aria-pressed.
          className="aria-pressed:[&_svg]:fill-current"
          aria-disabled={locked || undefined}
          onClick={() => void choose(choice)}
        >
          {icon}
        </IconButton>
      </Tooltip>
    )
  }

  const status =
    phase === 'submitting'
      ? 'Submitting feedback'
      : phase === 'failed'
        ? 'Feedback not sent. Try again.'
        : phase === 'submitted'
          ? detail === 'sent'
            ? 'Feedback submitted. Thank you for the detail.'
            : 'Feedback submitted'
          : ''

  return (
    <div role="group" aria-label="Feedback on this reply" className={cn('flex flex-col gap-2', className)}>
      <div className="flex items-center gap-1">
        {button('helpful', <ThumbsUp />)}
        {button('not-helpful', <ThumbsDown />)}
        <p
          ref={statusRef}
          role="status"
          tabIndex={-1}
          className="ml-2 font-body text-sm text-[var(--color-text-secondary)] focus:outline-none"
        >
          {status}
        </p>
      </div>
      {detail === 'open' ? (
        <div className="flex flex-col gap-2 max-w-md">
          <label htmlFor={`${id}-detail`} className="font-body text-sm text-[var(--color-text-primary)]">
            What was wrong with this reply? (optional)
          </label>
          <Textarea
            ref={boxRef}
            id={`${id}-detail`}
            rows={2}
            value={text}
            onChange={event => setText(event.target.value)}
          />
          <div className="flex gap-2">
            <Button size="sm" disabled={text.trim() === ''} onClick={() => closeDetail(true)}>
              Send
            </Button>
            <Button size="sm" variant="ghost" onClick={() => closeDetail(false)}>
              Dismiss
            </Button>
          </div>
        </div>
      ) : null}
    </div>
  )
}
